	, FactK12StudentAssessment.EnglishLearnerStatusId AS FactK12StudentAssessment_EnglishLearnerStatusId
	, FactK12StudentAssessment.FosterCareStatusId AS FactK12StudentAssessment_FosterCareStatusId
