	, FactK12StudentAssessment.AssessmentResultScoreValueScaleScore AS FactK12StudentAssessment_AssessmentResultScoreValueScaleScore
	, FactK12StudentAssessment.AssessmentResultScoreValuePercentile AS FactK12StudentAssessment_AssessmentResultScoreValuePercentile
	, FactK12StudentAssessment.AssessmentResultScoreValueTScore AS FactK12StudentAssessment_AssessmentResultScoreValueTScore
	, FactK12StudentAssessment.AssessmentResultScoreValueZScore AS FactK12StudentAssessment_AssessmentResultScoreValueZScore
	, FactK12StudentAssessment.AssessmentResultScoreValueACTScore AS FactK12StudentAssessment_AssessmentResultScoreValueACTScore
	, FactK12StudentAssessment.AssessmentResultScoreValueSATScore AS FactK12StudentAssessment_AssessmentResultScoreValueSATScore
	, FactK12StudentAssessment.AssessmentResultScoreValueACTSuperscore AS FactK12StudentAssessment_AssessmentResultScoreValueACTSuperscore
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorRawScore AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorRawScore
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorScaleScore AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorScaleScore
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorPercentile AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorPercentile
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorTScore AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorTScore
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorZScore AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorZScore
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorACTScore AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorACTScore
	, FactK12StudentAssessment.AssessmentResultScoreValueStandardErrorSATScore AS FactK12StudentAssessment_AssessmentResultScoreValueStandardErrorSATScore
	, AccessibilityFeature.AccessibilityFeatureTypeCode AS AccessibilityFeature_AccessibilityFeatureTypeCode
	, AccessibilityFeature.AccessibilityFeatureTypeDescription AS AccessibilityFeature_AccessibilityFeatureTypeDescription
	, AccessibilityFeature.AccessibilityFeatureApplicationTypeCode AS AccessibilityFeature_AccessibilityFeatureApplicationTypeCode
	, AccessibilityFeature.AccessibilityFeatureApplicationTypeDescription AS AccessibilityFeature_AccessibilityFeatureApplicationTypeDescription
	, AccessibilityFeature.AccessibilityFeatureCategoryCode AS AccessibilityFeature_AccessibilityFeatureCategoryCode
