	, AccessibilityFeature.AccessibilityFeaturePausesTheClockIndicatorDescription AS AccessibilityFeature_AccessibilityFeaturePausesTheClockIndicatorDescription
	, AccessibilityFeatureLanguageType.Iso6392LanguageCodeCode AS AccessibilityFeatureLanguageType_Iso6392LanguageCodeCode
	, AccessibilityFeatureLanguageType.Iso6392LanguageCodeDescription AS AccessibilityFeatureLanguageType_Iso6392LanguageCodeDescription
	, AccessibilityFeatureLanguageType.Iso6392LanguageCodeEdFactsCode AS AccessibilityFeatureLanguageType_Iso6392LanguageCodeEdFactsCode
	, AccessibilityFeatureLanguageType.Iso6393LanguageCodeCode AS AccessibilityFeatureLanguageType_Iso6393LanguageCodeCode
	, AccessibilityFeatureLanguageType.Iso6393LanguageCodeDescription AS AccessibilityFeatureLanguageType_Iso6393LanguageCodeDescription
	, AssessmentComponent.AssessmentComponentTypeCode AS AssessmentComponent_AssessmentComponentTypeCode
	, AssessmentComponent.AssessmentComponentTypeDescription AS AssessmentComponent_AssessmentComponentTypeDescription
	, AccessibilityFeatureBraille.BrailleAccessTypeCode AS AccessibilityFeatureBraille_BrailleAccessTypeCode
	, AccessibilityFeatureBraille.BrailleAccessTypeDescription AS AccessibilityFeatureBraille_BrailleAccessTypeDescription
	, AccessibilityFeatureBraille.BrailleApplicationTypeCode AS AccessibilityFeatureBraille_BrailleApplicationTypeCode
	, AccessibilityFeatureBraille.BrailleApplicationTypeDescription AS AccessibilityFeatureBraille_BrailleApplicationTypeDescription
	, AccessibilityFeatureBraille.BrailleCodeTypeCode AS AccessibilityFeatureBraille_BrailleCodeTypeCode
	, AccessibilityFeatureBraille.BrailleCodeTypeDescription AS AccessibilityFeatureBraille_BrailleCodeTypeDescription
	, AccessibilityFeatureBraille.BrailleVersionTypeCode AS AccessibilityFeatureBraille_BrailleVersionTypeCode
	, AccessibilityFeatureBraille.BrailleVersionTypeDescription AS AccessibilityFeatureBraille_BrailleVersionTypeDescription
	, AccessibilityFeatureCalculator.AdaptiveCalculatorTypeCode AS AccessibilityFeatureCalculator_AdaptiveCalculatorTypeCode
	, AccessibilityFeatureCalculator.AdaptiveCalculatorTypeDescription AS AccessibilityFeatureCalculator_AdaptiveCalculatorTypeDescription
	, AccessibilityFeatureCalculator.CalculatorTypeCode AS AccessibilityFeatureCalculator_CalculatorTypeCode
	, AccessibilityFeatureCalculator.CalculatorTypeDescription AS AccessibilityFeatureCalculator_CalculatorTypeDescription
	, AccessibilityFeatureBreak.BreakLocationTypeCode AS AccessibilityFeatureBreak_BreakLocationTypeCode
	, AccessibilityFeatureBreak.BreakLocationTypeDescription AS AccessibilityFeatureBreak_BreakLocationTypeDescription
	, AccessibilityFeatureBreak.BreakTypeCode AS AccessibilityFeatureBreak_BreakTypeCode
	, AccessibilityFeatureBreak.BreakTypeDescription AS AccessibilityFeatureBreak_BreakTypeDescription
	, AccessibilityFeatureSignedAdministration.SignedAdministrationDeliveryMethodCode AS AccessibilityFeatureSignedAdministration_SignedAdministrationDeliveryMethodCode
	, AccessibilityFeatureSignedAdministration.SignedAdministrationDeliveryMethodDescription AS AccessibilityFeatureSignedAdministration_SignedAdministrationDeliveryMethodDescription
	, AccessibilityFeatureSignedAdministration.SignedAdministrationTypeCode AS AccessibilityFeatureSignedAdministration_SignedAdministrationTypeCode
	, AccessibilityFeatureSignedAdministration.SignedAdministrationTypeDescription AS AccessibilityFeatureSignedAdministration_SignedAdministrationTypeDescription
	, AccessibilityFeatureAlternateResponseOption.AlternateResponseOptionTypeCode AS AccessibilityFeatureAlternateResponseOption_AlternateResponseOptionTypeCode
	, AccessibilityFeatureAlternateResponseOption.AlternateResponseOptionTypeDescription AS AccessibilityFeatureAlternateResponseOption_AlternateResponseOptionTypeDescription
	, AccessibilityFeatureAssessmentExtendedTime.AssessmentExtendedTimeTypeCode AS AccessibilityFeatureAssessmentExtendedTime_AssessmentExtendedTimeTypeCode
	, AccessibilityFeatureAssessmentExtendedTime.AssessmentExtendedTimeTypeDescription AS AccessibilityFeatureAssessmentExtendedTime_AssessmentExtendedTimeTypeDescription
	, AccessibilityFeatureDisplayFormatAdjustment.DisplayFormatAdjustmentTypeCode AS AccessibilityFeatureDisplayFormatAdjustment_DisplayFormatAdjustmentTypeCode
	, AccessibilityFeatureDisplayFormatAdjustment.DisplayFormatAdjustmentTypeDescription AS AccessibilityFeatureDisplayFormatAdjustment_DisplayFormatAdjustmentTypeDescription
	, AccessibilityFeatureGroupSize.GroupSizeTypeCode AS AccessibilityFeatureGroupSize_GroupSizeTypeCode
	, AccessibilityFeatureGroupSize.GroupSizeTypeDescription AS AccessibilityFeatureGroupSize_GroupSizeTypeDescription
	, AccessibilityFeatureMedicalSupport.MedicalSupportTypeCode AS AccessibilityFeatureMedicalSupport_MedicalSupportTypeCode
	, AccessibilityFeatureMedicalSupport.MedicalSupportTypeDescription AS AccessibilityFeatureMedicalSupport_MedicalSupportTypeDescription
	, AccessibilityFeatureReadAloud.ReadAloudTypeCode AS AccessibilityFeatureReadAloud_ReadAloudTypeCode
	, AccessibilityFeatureReadAloud.ReadAloudTypeDescription AS AccessibilityFeatureReadAloud_ReadAloudTypeDescription
	, AccessibilityFeatureReferenceSheet.ReferenceSheetTypeCode AS AccessibilityFeatureReferenceSheet_ReferenceSheetTypeCode
	, AccessibilityFeatureReferenceSheet.ReferenceSheetTypeDescription AS AccessibilityFeatureReferenceSheet_ReferenceSheetTypeDescription
	, AccessibilityFeatureSetting.SettingTypeCode AS AccessibilityFeatureSetting_SettingTypeCode
	, AccessibilityFeatureSetting.SettingTypeDescription AS AccessibilityFeatureSetting_SettingTypeDescription
	, AccessibilityFeatureTactileMedium.TactileMediumTypeCode AS AccessibilityFeatureTactileMedium_TactileMediumTypeCode
	, AccessibilityFeatureTactileMedium.TactileMediumTypeDescription AS AccessibilityFeatureTactileMedium_TactileMediumTypeDescription
	, AccessibilityFeatureTranslationPresentation.TranslationPresentationTypeCode AS AccessibilityFeatureTranslationPresentation_TranslationPresentationTypeCode
	, AccessibilityFeatureTranslationPresentation.TranslationPresentationTypeDescription AS AccessibilityFeatureTranslationPresentation_TranslationPresentationTypeDescription
	, fact.AssessmentExtendedTimeDuration
	, fact.BreakDuration
	, fact.GroupSizeRangeMaximum
	, fact.GroupSizeRangeMinimum
	, fact.AdaptiveAndSpecializedEquipmentOrFurnitureDescription
FROM RDS.BridgeK12StudentAssessmentAccessibilityFeatures fact
JOIN RDS.FactK12StudentAssessments FactK12StudentAssessment
	ON fact.FactK12StudentAssessmentId = FactK12StudentAssessment.FactK12StudentAssessmentId
JOIN RDS.DimAccessibilityFeatures AccessibilityFeature
	ON fact.AccessibilityFeatureId = AccessibilityFeature.DimAccessibilityFeatureId
JOIN RDS.DimLanguages AccessibilityFeatureLanguageType
	ON fact.AccessibilityFeatureLanguageTypeId = AccessibilityFeatureLanguageType.DimLanguageId
JOIN RDS.DimAssessmentComponents AssessmentComponent
	ON fact.AssessmentComponentId = AssessmentComponent.DimAssessmentComponentId
JOIN RDS.DimAccessibilityFeatureBrailles AccessibilityFeatureBraille
	ON fact.AccessibilityFeatureBrailleId = AccessibilityFeatureBraille.DimAccessibilityFeatureBrailleId
JOIN RDS.DimAccessibilityFeatureCalculators AccessibilityFeatureCalculator
	ON fact.AccessibilityFeatureCalculatorId = AccessibilityFeatureCalculator.DimAccessibilityFeatureCalculatorId
JOIN RDS.DimAccessibilityFeatureBreaks AccessibilityFeatureBreak
	ON fact.AccessibilityFeatureBreakId = AccessibilityFeatureBreak.DimAccessibilityFeatureBreakId
JOIN RDS.DimAccessibilityFeatureSignedAdministrations AccessibilityFeatureSignedAdministration
	ON fact.AccessibilityFeatureSignedAdministrationId = AccessibilityFeatureSignedAdministration.DimAccessibilityFeatureSignedAdministrationId
JOIN RDS.DimAccessibilityFeatureAlternateResponseOptions AccessibilityFeatureAlternateResponseOption
	ON fact.AccessibilityFeatureAlternateResponseOptionId = AccessibilityFeatureAlternateResponseOption.DimAccessibilityFeatureAlternateResponseOptionId
JOIN RDS.DimAccessibilityFeatureAssessmentExtendedTimes AccessibilityFeatureAssessmentExtendedTime
	ON fact.AccessibilityFeatureAssessmentExtendedTimeId = AccessibilityFeatureAssessmentExtendedTime.DimAccessibilityFeatureAssessmentExtendedTimeId
JOIN RDS.DimAccessibilityFeatureDisplayFormatAdjustments AccessibilityFeatureDisplayFormatAdjustment
	ON fact.AccessibilityFeatureDisplayFormatAdjustmentId = AccessibilityFeatureDisplayFormatAdjustment.DimAccessibilityFeatureDisplayFormatAdjustmentId
JOIN RDS.DimAccessibilityFeatureGroupSizes AccessibilityFeatureGroupSize
	ON fact.AccessibilityFeatureGroupSizeId = AccessibilityFeatureGroupSize.DimAccessibilityFeatureGroupSizeId
JOIN RDS.DimAccessibilityFeatureMedicalSupports AccessibilityFeatureMedicalSupport
	ON fact.AccessibilityFeatureMedicalSupportId = AccessibilityFeatureMedicalSupport.DimAccessibilityFeatureMedicalSupportId
JOIN RDS.DimAccessibilityFeatureReadAlouds AccessibilityFeatureReadAloud
	ON fact.AccessibilityFeatureReadAloudId = AccessibilityFeatureReadAloud.DimAccessibilityFeatureReadAloudId
JOIN RDS.DimAccessibilityFeatureReferenceSheets AccessibilityFeatureReferenceSheet
	ON fact.AccessibilityFeatureReferenceSheetId = AccessibilityFeatureReferenceSheet.DimAccessibilityFeatureReferenceSheetId
JOIN RDS.DimAccessibilityFeatureSettings AccessibilityFeatureSetting
	ON fact.AccessibilityFeatureSettingId = AccessibilityFeatureSetting.DimAccessibilityFeatureSettingId
JOIN RDS.DimAccessibilityFeatureTactileMediums AccessibilityFeatureTactileMedium
	ON fact.AccessibilityFeatureTactileMediumId = AccessibilityFeatureTactileMedium.DimAccessibilityFeatureTactileMediumId
JOIN RDS.DimAccessibilityFeatureTranslationPresentations AccessibilityFeatureTranslationPresentation
	ON fact.AccessibilityFeatureTranslationPresentationId = AccessibilityFeatureTranslationPresentation.DimAccessibilityFeatureTranslationPresentationId
